import 'package:flutter_test/flutter_test.dart';
import 'package:groopx/features/calls/data/call_api.dart';
import 'package:groopx/features/chat/domain/chat_models.dart';
import 'package:groopx/features/contacts/data/social_api.dart';
import 'package:groopx/features/status/data/status_api.dart';

void main(){
  test('shared media parses server payload',(){final item=SharedMediaItem.fromJson({'id':'media-1','kind':'image','attachment':{'url':'https://cdn.example/photo.jpg','file_name':'photo.jpg'},'created_at':'2026-09-21T10:00:00Z'});expect(item.name,'photo.jpg');expect(item.url,contains('photo.jpg'));});
  test('call history parses server payload',(){final item=CallHistoryItem.fromJson({'id':'call-1','conversation_id':'conversation-1','title':'Design Team','kind':'video','status':'ended','avatar_url':'','started_at':'2026-09-21T10:00:00Z'});expect(item.kind,'video');expect(item.title,'Design Team');});
  test('group preview includes the latest sender',(){final item=ChatSummary.fromJson({'id':'group-1','kind':'group','title':'Family','preview':'Dinner at 8','preview_sender_name':'Pooja','preview_mine':false});expect(item.displayPreview,'Pooja: Dinner at 8');expect(ChatSummary.fromJson(item.toJson()).displayPreview,'Pooja: Dinner at 8');});
  test('own group preview uses You label',(){final item=ChatSummary.fromJson({'id':'group-1','kind':'group','title':'Family','preview':'On my way','preview_sender_name':'Vinod','preview_mine':true});expect(item.displayPreview,'You: On my way');});
  test('direct preview stays unchanged',(){final item=ChatSummary.fromJson({'id':'direct-1','kind':'direct','title':'Pooja','preview':'Hello','preview_sender_name':'Pooja'});expect(item.displayPreview,'Hello');});
  test('reaction detail parses reactor identity',(){final item=MessageReactionDetail.fromJson({'emoji':'❤️','user_id':'user-1','name':'Pooja','avatar_url':'https://cdn.example/avatar.jpg','mine':true,'created_at':'2026-10-19T10:00:00Z'});expect(item.emoji,'❤️');expect(item.name,'Pooja');expect(item.mine,isTrue);expect(item.createdAt,isNotNull);});
  test('chat summary updates live presence without changing content',(){final item=ChatSummary.fromJson({'id':'direct-1','kind':'direct','title':'Pooja','preview':'Hello','online':false});final online=item.copyWith(online:true);expect(online.online,isTrue);expect(online.name,'Pooja');expect(item.online,isFalse);});
  test('chat summary preserves pinned state in cache and live updates',(){final item=ChatSummary.fromJson({'id':'direct-1','kind':'direct','title':'Pooja','preview':'Hello','pinned':true});expect(item.pinned,isTrue);expect(ChatSummary.fromJson(item.toJson()).pinned,isTrue);expect(item.copyWith(online:true).pinned,isTrue);});
  test('global message search result keeps conversation target',(){final item=GlobalMessageSearchResult.fromJson({'id':'message-1','conversation_id':'chat-1','conversation_kind':'group','conversation_title':'Family','sender_name':'Pooja','text':'Dinner at 8','created_at':'2026-10-20T12:00:00Z','mine':false});expect(item.messageId,'message-1');expect(item.conversationId,'chat-1');expect(item.group,isTrue);expect(item.conversationTitle,'Family');});
  test('live location session parses active device state',(){final item=LiveLocationSession.fromJson({'id':'live-1','message_id':'message-1','conversation_id':'chat-1','expires_at':'2099-10-23T12:00:00Z','updated_at':'2026-10-23T11:00:00Z'});expect(item.messageId,'message-1');expect(item.conversationId,'chat-1');expect(item.active,isTrue);});
  test('shared location uses map URL and label',(){final item=SharedMediaItem.fromJson({'id':'location-1','kind':'location','attachment':{'map_url':'https://www.google.com/maps/search/?api=1&query=0,0','label':'Live location'},'created_at':'2026-10-23T11:00:00Z'});expect(item.url,contains('query=0,0'));expect(item.name,'Live location');});
  test('contact message preserves share card metadata',(){final item=ChatMessage.fromJson({'id':'contact-1','kind':'contact','text':'Contact: Pooja Sharma','mine':false,'attachment':{'display_name':'Pooja Sharma','phone':'+917056407000'}});expect(item.isAttachment,isTrue);expect(item.attachment?['display_name'],'Pooja Sharma');expect(item.attachment?['phone'],'+917056407000');});
  test('poll message preserves choices and current vote',(){final item=ChatMessage.fromJson({'id':'poll-message-1','kind':'poll','text':'Poll: Meeting time?','mine':false,'attachment':{'poll_id':'poll-1','question':'Meeting time?','allow_multiple':false,'closed':false,'total_votes':2,'total_voters':2,'options':[{'id':'option-1','text':'10 AM','votes':2,'selected':true},{'id':'option-2','text':'4 PM','votes':0,'selected':false}]}});expect(item.isAttachment,isTrue);expect(item.attachment?['poll_id'],'poll-1');expect((item.attachment?['options'] as List).first['selected'],isTrue);expect(item.attachment?['total_voters'],2);});
  test('view once media preserves protected state',(){final item=ChatMessage.fromJson({'id':'view-1','kind':'image','text':'View once photo','mine':false,'attachment':{'view_once':true,'opened':false,'available':true,'opened_count':0,'recipient_count':1}});expect(item.viewOnce,isTrue);expect(item.viewOnceOpened,isFalse);expect(item.attachment?['url'],isNull);});
  test('group mention survives cache and marks recipient',(){final item=ChatMessage.fromJson({'id':'message-mention-1','kind':'text','text':'Hi @pooja','mine':false,'mentioned':true,'mention_user_ids':['user-pooja']});expect(item.mentioned,isTrue);expect(item.mentionUserIds,['user-pooja']);final cached=ChatMessage.fromJson(item.toJson());expect(cached.mentioned,isTrue);expect(cached.mentionUserIds,['user-pooja']);});
  test('announcement group details preserve send permission',(){final item=ConversationDetails.fromJson({'title':'Company updates','kind':'group','member_count':18,'announcement_only':true,'can_send':false,'admin':false});expect(item.group,isTrue);expect(item.announcementOnly,isTrue);expect(item.canSend,isFalse);expect(item.admin,isFalse);expect(item.copyWith(online:true).canSend,isFalse);});
  test('group settings parse announcement approval and member permissions',(){final item=GroupDetails.fromJson({'id':'group-1','name':'Company updates','description':'Official news','privacy':'private','avatar_url':'','announcement_only':true,'join_approval_required':true,'members_can_edit_info':true,'members_can_add_members':false,'admin':false,'can_edit_info':true,'can_add_members':false,'pending_join_requests':3,'members':[]});expect(item.announcementOnly,isTrue);expect(item.joinApprovalRequired,isTrue);expect(item.membersCanEditInfo,isTrue);expect(item.membersCanAddMembers,isFalse);expect(item.admin,isFalse);expect(item.canEditInfo,isTrue);expect(item.canAddMembers,isFalse);expect(item.pendingJoinRequests,3);expect(item.name,'Company updates');});
  test('group member page preserves aliases pagination and capabilities',(){final page=GroupMemberPage.fromJson({'items':[{'id':'user-1','name':'Maa','profile_name':'Pooja','display_name':'Maa','username':'pooja','avatar_url':'https://cdn.example/avatar.jpg','mention':'@pooja','role':'admin','mine':false}],'total':42,'limit':20,'offset':20,'has_more':true,'admin':true,'can_add_members':true});expect(page.items.single.name,'Maa');expect(page.items.single.profileName,'Pooja');expect(page.items.single.displayName,'Maa');expect(page.items.single.avatarUrl,contains('avatar.jpg'));expect(page.items.single.role,'admin');expect(page.total,42);expect(page.offset,20);expect(page.hasMore,isTrue);expect(page.admin,isTrue);expect(page.canAddMembers,isTrue);});
  test('invite join result parses pending approval',(){final item=InviteJoinResult.fromJson({'group_id':'group-1','kind':'group','status':'pending','message':'Request sent','request_id':'request-1'});expect(item.pending,isTrue);expect(item.requestId,'request-1');expect(item.message,'Request sent');});
  test('group join request keeps public profile fields',(){final item=GroupJoinRequest.fromJson({'id':'request-1','user_id':'user-1','name':'Pooja','username':'pooja','avatar_url':'https://cdn.example/avatar.jpg','requested_at':'2026-10-25T10:30:00Z'});expect(item.name,'Pooja');expect(item.username,'pooja');expect(item.avatarUrl,contains('avatar.jpg'));expect(item.requestedAt,isA<DateTime>());});
  test('group invite keeps usage and server status',(){final item=GroupInvite.fromJson({'id':'invite-1','creator_name':'Vinod','expires_at':'2026-10-26T10:30:00Z','created_at':'2026-10-25T10:30:00Z','max_uses':50,'use_count':12,'status':'active'});expect(item.active,isTrue);expect(item.remainingUses,38);expect(item.creatorName,'Vinod');});
  test('created group invite keeps copyable secret link',(){final item=CreatedGroupInvite.fromJson({'id':'invite-2','invite_link':'groopx:///join/secret','expires_at':'2026-10-26T10:30:00Z','created_at':'2026-10-25T10:30:00Z','max_uses':25});expect(item.link,'groopx:///join/secret');expect(item.maxUses,25);});
  test('community details preserve member and linked group counts',(){final item=CommunityDetails.fromJson({'id':'community-1','name':'Neighbours','description':'Building updates','role':'admin','member_count':14,'groups':[{'id':'group-1','name':'Building A','member_count':8}]});expect(item.memberCount,14);expect(item.groups.single.memberCount,8);expect(item.role,'admin');});
  test('group activity parses as a centered non attachment message',(){final item=ChatMessage.fromJson({'id':'system-1','kind':'system','text':'Vinod added Pooja','created_at':'2026-10-25T12:00:00Z','mine':false,'attachment':{'event':'member_added'}});expect(item.system,isTrue);expect(item.isAttachment,isFalse);expect(item.text,'Vinod added Pooja');});
  test('status item preserves muted state',(){final item=StatusItem.fromJson({'id':'status-1','user_id':'user-1','user_name':'Pooja','avatar_url':'','media_url':'https://cdn.example/status.jpg','media_type':'image','caption':'Hello','mine':false,'viewed':true,'muted':true,'view_count':3,'created_at':'2026-10-26T10:00:00Z'});expect(item.muted,isTrue);expect(item.viewed,isTrue);expect(item.copyWith(muted:false).muted,isFalse);});
  test('status privacy parses audience contacts and selections',(){final settings=StatusPrivacySettings.fromJson({'audience':'contacts_except','contacts':[{'id':'user-1','name':'Pooja','username':'pooja','avatar_url':'','selected':true},{'id':'user-2','name':'Aman','selected':false}]});expect(settings.audience,'contacts_except');expect(settings.contacts.length,2);expect(settings.selectedUserIds,{'user-1'});});
}
